{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.03,
  "summary": [
    "Historical base-rate: AfD has never won the most seats in Baden-Württemberg, with Greens or CDU leading in past elections.",
    "Recent credible polls place CDU/Greens ahead of AfD, with AfD typically around 18–21%, not the top party.",
    "Coalition dynamics imply AfD is excluded from government-forming coalitions, reducing chances of a top-seat outcome.",
    "A small risk of late momentum reversals exists but remains insufficient to overcome the strong base-rate."
  ],
  "confidence": "low",
  "narrative": "Using the Baden-Württemberg reference class, the base-rate strongly disfavors AfD top-seat outcomes. Updates from polls and coalition dynamics push the probability toward near-zero, yielding a 1% posterior with wide uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.03,
      "basis": "Reference class is Baden-Württemberg state elections since 2016, where AfD has never led the seat count; anchor probability chosen to reflect a modest base-rate derived from historical pattern before applying updates."
    },
    "factor_updates": [
      {
        "factor": "Historical base-rate: AfD has never won the most seats in Baden-Württemberg",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Past results show Greens or CDU dominance; historically AfD has not topped seat counts, anchoring expectations away from an AfD top-seat outcome."
      },
      {
        "factor": "Credible polls place CDU/Greens ahead of AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Late-2025/early-2026 polls show CDU/Greens leading; AfD in the high teens to low twenties, not top; this reduces chance of AfD winning most seats."
      },
      {
        "factor": "Coalition dynamics: AfD excluded from government coalitions",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Major parties in BW generally reject AfD, making an AfD-led majority improbable."
      },
      {
        "factor": "Momentum reversals in BW Trend",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Some readings suggested AfD could edge ahead of Greens; such momentum, if sustained, could raise probability, albeit still unlikely."
      },
      {
        "factor": "Turnout and thresholds",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "5% threshold and turnout variations have historically not produced AfD-led majorities; effect on probability is limited."
      }
    ],
    "synthesis_rationale": "The posterior probability of AfD leading the most seats is the result of starting from a modest base-rate (anchor ~3%), applying several strong downward updates from historical precedent, polling data, and coalition constraints, with only a small upward tilt from rare momentum or turnout shifts. Given possible correlations among polls and momentum signals, a calibrated posterior of 1% is plausible; the final range reflects substantial uncertainty around a tiny likelihood."
  }
}

{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.04,
  "summary": [
    "Historical base-rate: AfD has never won the most seats in Baden-Württemberg, anchoring the prior probability near zero.",
    "Credible polls consistently show CDU or Greens ahead of AfD, with AfD polling roughly 18–21% in late 2025–early 2026.",
    "Coalition dynamics exclude AfD (firewall against AfD-led majority), further suppressing top-seat chances.",
    "Minor late shifts (momentum or turnout) could modestly elevate AfD but are unlikely to overturn the lead of CDU/Greens."
  ],
  "confidence": "high",
  "narrative": "Bayesian updating from a low historical base-rate and current polls places AfD's probability of winning the most seats at about 1%. Even with a potential late momentum shift, the probability remains very small given coalition dynamics and past results.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "Historical reference class: Baden-Württemberg elections show AfD has never led the seat tally; thus a modest starting anchor around 5%."
    },
    "factor_updates": [
      {
        "factor": "Historical base-rate",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Past outcomes show Greens or CDU leading; AfD has never topped seats (2016 Greens 47/143; 2021 Greens 58/154; AfD 0 seats in 2021)."
      },
      {
        "factor": "Credible polls place CDU/Greens ahead of AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Polls consistently show CDU around 28–29%, Greens near 20–27%, AfD around 18–21%, not leading."
      },
      {
        "factor": "Coalition dynamics exclude AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Major parties in BW refuse coalitions with AfD, reducing path to a top-seat government."
      },
      {
        "factor": "Momentum reversals in BW Trend",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Some readings have shown AfD leading Greens; if momentum persists, risk increases slightly."
      },
      {
        "factor": "Turnout and thresholds effects",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "5% threshold and turnout volatility can alter seat counts but historically have not produced AfD-led majority."
      },
      {
        "factor": "Late shocks or events",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Unpredictable events could shift votes temporarily, though unlikely to erase leading party advantage."
      }
    ],
    "synthesis_rationale": "Cumulative downward pressure from the base-rate and polls dominates; occasional upside from momentum or turnout is acknowledged but not enough to overcome sustained gaps in polls and history. The final posterior is placed at 1% with a narrow uncertainty range reflecting potential late shifts, while noting possible correlations among factors."
  }
}

{
