  "narrative": "While the reference pattern and polls argue against AfD topping the seat tally, a small tail-risk exists if late momentum shifts significantly boost AfD support or suppress Greens and/or CDU gains. The estimate captures this with a low-probability scenario within a broad uncertainty range.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "reference class: Baden-Württemberg state elections since 2016 where AfD has not topped seats; anchor chosen to reflect a very low base-rate probability based on historical outcomes and current polls."
    },
    "factor_updates": [
      {
        "factor": "Historical base-rate: AfD has never won the most seats in Baden-Württemberg",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Historical results show Greens or CDU leading; this remains a strong drag on AfD-top scenarios."
      },
      {
        "factor": "Credible polls place CDU/Greens ahead of AfD (AfD ~18–21%)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Polls strongly favor CDU/Greens over AfD; this lowers probability of AfD topping seats."
      },
      {
        "factor": "Coalition dynamics exclude AfD from governing coalitions (firewall)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Major parties likely to exclude AfD; even if AfD tops vote share, seat tally unlikely to be majority without coalition."
